//! Build-time app metadata. Generated files are private, disposable build inputs.
//! Generation never contacts the engine or initializes a volume.
use super::{Manifest, Result, codec::MAX_WASM_BYTES};
use std::{
    fs,
    io::Read,
    path::{Path, PathBuf},
};

pub const DIRECTORY: &str = "target/playbit";
pub const MAX_NATIVE_BYTES: usize = 128 * 1024 * 1024;
const SECTION: &str = "playbit.metadata";

pub fn fingerprint(manifest: &Manifest) -> Result<[u8; 32]> {
    if let Some(trace) = &manifest.trace {
        trace.validate()?;
    }
    let bytes = serde_json::to_vec(&manifest.trace)?;
    Ok(*blake3::hash(&bytes).as_bytes())
}

/// Compare before replacing: no-op preparation must not trigger recompilation.
/// A same-directory temporary file makes each replacement atomic.
pub fn write_changed(path: &Path, bytes: &[u8]) -> Result<()> {
    match fs::File::open(path) {
        Ok(file) => {
            let mut prior = Vec::new();
            file.take(bytes.len() as u64 + 1).read_to_end(&mut prior)?;
            if prior == bytes {
                return Ok(());
            }
        }
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
        Err(error) => return Err(error.into()),
    }
    let temporary = path.with_extension(format!("tmp-{}", std::process::id()));
    let result = (|| {
        fs::write(&temporary, bytes)?;
        fs::rename(&temporary, path)?;
        Ok(())
    })();
    if result.is_err() {
        let _ = fs::remove_file(&temporary);
    }
    result
}

pub fn generate(directory: &Path, manifest: &Manifest) -> Result<PathBuf> {
    // Complete validation and generation before touching the previous output.
    let hash = fingerprint(manifest)?;
    let mut source = match &manifest.trace {
        Some(trace) => trace.constants()?,
        None => String::from("// Generated by pb meta-gen. Do not edit.\n"),
    };
    source.push_str(&format!(
        r#"
#[used]
#[allow(unsafe_code, reason = "Read-only build metadata in a dedicated object section.")]
#[cfg_attr(target_arch = "wasm32", unsafe(link_section = "playbit.metadata"))]
#[cfg_attr(target_os = "macos", unsafe(link_section = "__DATA,__pbmeta"))]
static PLAYBIT_METADATA: [u8; 32] = {hash:?};
"#
    ));
    let output = directory.join(DIRECTORY);
    fs::create_dir_all(&output)?;
    write_changed(&output.join("metadata.rs"), source.as_bytes())?;
    Ok(output)
}

fn matches(expected: &[u8; 32], actual: Option<&[u8]>, required: bool) -> bool {
    match actual {
        Some(bytes) => bytes == expected,
        None => !required,
    }
}
fn check(manifest: &Manifest, found: Option<&[u8]>) -> Result<()> {
    if matches(&fingerprint(manifest)?, found, manifest.trace.is_some()) {
        return Ok(());
    }
    Err("app metadata differs from playbit.toml; run pb build to regenerate and recompile".into())
}

pub fn check_wasm(manifest: &Manifest, wasm: &[u8]) -> Result<()> {
    if wasm.len() > MAX_WASM_BYTES {
        return Err("Wasm executable exceeds 64 MiB".into());
    }
    let mut found = None;
    for payload in wasmparser::Parser::new(0).parse_all(wasm) {
        if let wasmparser::Payload::CustomSection(section) = payload?
            && section.name() == SECTION
        {
            if found.is_some() {
                return Err("duplicate app metadata section".into());
            }
            found = Some(section.data());
        }
    }
    check(manifest, found)
}

#[cfg(not(target_arch = "wasm32"))]
pub fn check_native(
    manifest: &Manifest,
    package: &super::Package,
    executable: &[u8],
) -> Result<()> {
    use object::{Object, ObjectSection};
    if executable.len() > MAX_NATIVE_BYTES {
        return Err("native executable exceeds 128 MiB".into());
    }
    let file = object::File::parse(executable)?;
    let mut found = None;
    let mut digest = None;
    for section in file.sections() {
        match section.name()? {
            "__pbbundle" => {
                if digest.is_some() {
                    return Err("duplicate native package digest".into());
                }
                digest = Some(section.data()?);
            }
            "__pbmeta" => {
                if found.is_some() {
                    return Err("duplicate native metadata".into());
                }
                found = Some(section.data()?);
            }
            _ => {}
        }
    }
    if digest != Some(package.digest().as_slice())
        || package.app_id() != manifest.app_id
        || package.name() != manifest.name
        || package.required_host_features() != manifest.required_host_features
        || package.trace().map(|bytes| bytes.as_ref())
            != manifest
                .trace
                .as_ref()
                .map(|trace| super::json::encode(trace, super::trace_catalog::MAX_BYTES))
                .transpose()?
                .as_deref()
    {
        return Err("native executable differs from paired package; run pb build --native".into());
    }
    check(manifest, found)
}

#[cfg(test)]
#[allow(clippy::unwrap_used, reason = "Tests assert fixture construction.")]
mod tests {
    use super::*;
    fn manifest() -> Manifest {
        Manifest::from_source(include_str!("../../../guests/todo/playbit.toml")).unwrap()
    }
    fn wasm(bytes: &[u8]) -> Vec<u8> {
        use wasm_encoder::{CustomSection, Module};
        let mut module = Module::new();
        module.section(&CustomSection { name: SECTION.into(), data: bytes.into() });
        module.finish()
    }
    #[test]
    fn packaging_rejects_stale_missing_duplicate_and_malformed_metadata() {
        let mut manifest = manifest();
        let hash = fingerprint(&manifest).unwrap();
        let bytes = wasm(&hash);
        assert!(check_wasm(&manifest, &bytes).is_ok());
        assert!(check_wasm(&manifest, b"\0asm\x01\0\0\0").is_err());
        assert!(check_wasm(&manifest, &wasm(&hash[..31])).is_err());
        let mut duplicate = bytes.clone();
        duplicate.extend_from_slice(&bytes[8..]);
        assert!(check_wasm(&manifest, &duplicate).is_err());
        for length in 0..bytes.len() {
            assert!(check_wasm(&manifest, &bytes[..length]).is_err());
        }
        manifest.trace.as_mut().unwrap().names.swap(0, 1);
        assert!(check_wasm(&manifest, &bytes).is_err());
        manifest.trace = None;
        assert!(check_wasm(&manifest, &bytes).is_err());
        assert!(check_wasm(&manifest, b"\0asm\x01\0\0\0").is_ok());
    }
    #[cfg(not(target_arch = "wasm32"))]
    fn macho(sections: &[(&str, &[u8])]) -> Vec<u8> {
        // Minimal arm64 Mach-O with one LC_SEGMENT_64 and inline section data.
        let command_size = 72 + 80 * sections.len();
        let mut bytes = vec![0; 32 + command_size];
        for (offset, value) in [
            (0, 0xfeedfacf_u32),
            (4, 0x0100_000c),
            (12, 2),
            (16, 1),
            (20, command_size as u32),
            (32, 0x19),
            (36, command_size as u32),
            (96, sections.len() as u32),
        ] {
            bytes[offset..offset + 4].copy_from_slice(&value.to_le_bytes());
        }
        for (index, (name, data)) in sections.iter().enumerate() {
            let start = 104 + index * 80;
            bytes[start..start + name.len()].copy_from_slice(name.as_bytes());
            bytes[start + 16..start + 22].copy_from_slice(b"__DATA");
            bytes[start + 40..start + 48].copy_from_slice(&(data.len() as u64).to_le_bytes());
            let offset = bytes.len() as u32;
            bytes[start + 48..start + 52].copy_from_slice(&offset.to_le_bytes());
            bytes.extend_from_slice(data);
        }
        bytes
    }
    #[cfg(not(target_arch = "wasm32"))]
    #[test]
    fn native_sections_bind_the_exact_portable_package() {
        // Native metadata binds the paired digest and current manifest identity.
        let mut manifest = manifest();
        let hash = fingerprint(&manifest).unwrap();
        let package = manifest
            .bundle(&Path::new(env!("CARGO_MANIFEST_DIR")).join("../guests/todo"), wasm(&hash))
            .unwrap();
        let digest = package.digest();
        let sections = [("__pbmeta", hash.as_slice()), ("__pbbundle", digest.as_slice())];
        assert!(check_native(&manifest, &package, &macho(&sections)).is_ok());
        assert!(check_native(&manifest, &package, &macho(&sections[..1])).is_err());
        let mut duplicate = sections.to_vec();
        duplicate.push(sections[1]);
        assert!(check_native(&manifest, &package, &macho(&duplicate)).is_err());
        let different = package.renamed("Different").unwrap();
        assert!(check_native(&manifest, &different, &macho(&sections)).is_err());
        manifest.app_id = "todo.testing".into();
        assert!(check_native(&manifest, &package, &macho(&sections)).is_err());
    }
}
